dtsPropsFor.StatusDot:
/** UI-11: the status axis is always a circle — filled for connected/connecting/failed, outline for disc/unknown. `connecting` adds a pulse ring. */
status: 'connected' | 'connecting' | 'failed' | 'disc' | 'unknown';
/** Diameter in px: 8 = server rows (default), 7 = the tab strip, 6 = tunnel cards. */
size?: 6 | 7 | 8;

dtsPropsFor.GroupHeader:
/** Group name; rendered upper-cased. */
group: string;
/** Servers in the group — stays visible while collapsed. */
count: number;
/** Drives the folder glyph: closed when true, open when false. */
collapsed: boolean;
/** The whole header is the collapse toggle. */
onToggle: () => void;

dtsPropsFor.TagsEditor:
/** The whole ServerForm value object — this editor reads and rewrites `form.tags`. */
form: { name: string; host: string; port: number | ''; user: string; authType: string; keyPath: string; password: string; passphrase: string; totpSecret: string; twoFactor: boolean; group: string; environment: string; tags: string[]; notes: string; jumpId: string | null };
/** Always called with a NEW object (and a new `tags` array) — never mutated in place. */
setForm: (form: TagsEditorProps['form']) => void;

dtsPropsFor.ServerFormGroup:
form: { name: string; host: string; port: number | ''; user: string; authType: string; keyPath: string; password: string; passphrase: string; totpSecret: string; twoFactor: boolean; group: string; environment: string; tags: string[]; notes: string; jumpId: string | null };
setForm: (form: ServerFormGroupProps['form']) => void;
/** Deduped, sorted group names already in use. Picking "+ New group…" swaps the select for a text input. */
groups: string[];

dtsPropsFor.TwoFactorFields:
form: { name: string; host: string; port: number | ''; user: string; authType: string; keyPath: string; password: string; passphrase: string; totpSecret: string; twoFactor: boolean; group: string; environment: string; tags: string[]; notes: string; jumpId: string | null };
setForm: (form: TwoFactorFieldsProps['form']) => void;
/** Editing an existing server — adds the "leave blank to keep the current secret" hint (SEC-01: a stored secret is never read back). */
editing: boolean;

dtsPropsFor.DestFields:
/** Tailwind class string for the two inputs — passed down by the parent form so every field shares one definition. NOT a field name. */
field: string;
/** Tailwind class string for the two labels. NOT the label text. */
label: string;
destHost: string;
setDestHost: (v: string) => void;
/** '' while the box is empty, so a cleared port doesn't become 0. */
destPort: number | '';
setDestPort: (v: number | '') => void;

dtsPropsFor.CodeRow:
serverName: string;
/** The 6-digit TOTP code; rendered split 3+3. */
code: string;
/** Seconds left in the shared 30s window — owned by the panel so every row rolls over together. */
remaining: number;

dtsPropsFor.Row:
label: string;
/** Secondary line under the label. */
hint?: string;
/** Inline chip next to the label (e.g. ProdBadge) — never the env square, which is reserved for the environment axis (UI-11). */
badge?: React.ReactNode;
/** The control(s) on the right. */
children: React.ReactNode;
/** Drops the bottom divider on the last row of a section. */
last?: boolean;

dtsPropsFor.TerminalPreview:
fontSize: number;
/** 'block' | 'bar' | 'underline' — a plain string, matching Settings.termCursor over the wire. */
cursor: string;
blink: boolean;

dtsPropsFor.Stepper:
value: number;
onChange: (v: number) => void;
min: number;
max: number;
/** Rendered straight after the value, e.g. 'px'. */
suffix?: string;

dtsPropsFor.Segmented:
value: string;
options: { value: string; label: string }[];
onChange: (v: string) => void;

dtsPropsFor.NumberBox:
value: number;
onChange: (v: number) => void;
min: number;
max: number;
/** Trailing unit label inside the box, e.g. 'lines'. */
unit?: string;

dtsPropsFor.InertSelect:
/** The single value this dropdown-shaped control displays. It cannot be opened — used where the design shows a picker but only one value exists. */
value: string;
/** Optional leading element, e.g. ThemeSwatch. */
leading?: React.ReactNode;
/** Render the value in the mono family. */
mono?: boolean;
/** Native tooltip explaining why there is nothing else to pick. */
title: string;

dtsPropsFor.ConfirmModal:
title: string;
message: string;
confirmLabel: string;
/** Red confirm button (Delete/Overwrite) instead of the accent one. */
danger?: boolean;
onConfirm: () => void;
/** Also fired by Escape. */
onCancel: () => void;

dtsPropsFor.PromptModal:
title: string;
/** Field label above the input. */
label: string;
initialValue: string;
confirmLabel: string;
/** Fired with the trimmed value; Enter submits only once it is non-blank. */
onSubmit: (value: string) => void;
/** Also fired by Escape. */
onCancel: () => void;

dtsPropsFor.FindBar:
/** Fired on every keystroke and on Enter / Shift+Enter. */
onFind: (query: string, dir: 'next' | 'prev') => void;
onClose: () => void;
/** addon-search's report. resultIndex is -1 when the active match is unknown (more matches than the highlight limit), which renders as `N+`. */
results: { resultIndex: number; resultCount: number } | null;

dtsPropsFor.PaneNotice:
/** 'failed' = an open that never connected (Retry); 'dropped' = an established session that died (Reconnect). */
kind: 'failed' | 'dropped';
/** Detail appended after the headline; may be empty. */
message: string;
onAction: () => void;

dtsPropsFor.ContextMenu:
/** Viewport coordinates of the click; clamped so the menu never spills off-screen. */
x: number;
y: number;
items: ({ label: string; run: () => void; danger?: boolean; disabled?: boolean; keepOpen?: boolean } | 'separator')[];
/** Fired by Escape, an outside click, and an outside right-click. */
onClose: () => void;

dtsPropsFor.Select:
/** The selected value (string or number). */
value: string | number;
/** Each option; `adornment` is an optional leading node, e.g. an environment colour square. */
options: { value: string | number; label: string; adornment?: React.ReactNode }[];
onChange: (v: string | number) => void;
/** Accessible name for the trigger button. */
ariaLabel?: string;
/** Start opened (uncontrolled) — used to show the option list in previews. */
defaultOpen?: boolean;
